@startuml

class Employee {
  + Name : string
  + Department : string
  + StaffNumber : string
}

class IdentityCard {
  + CardNumber : string
  + Department : string
  + StaffNumber : string
}

class GuestCard {
  + CardNumber : string
  + CurrentDate : date
}

class Car {
  + LicensePlate : string
}

class CarPark {
  + IsFull : boolean
}

class Barrier {
  + IsRaised : boolean
}

class CardReader {
  + VerifyCard(cardNumber: string) : boolean
}

class Reception {
  + CollectGuestCard(card: GuestCard) : void
}

Employee "1" -- "1" IdentityCard
IdentityCard "1" -- "1" Car "1" : drives
Car "1" -- "1" Barrier : passes
CarPark "1" -- "2" Barrier : has
CarPark "1" -- "0..*" Car : contains
CardReader "1" -- "1" Barrier : triggers
CardReader "1" -- "0..*" IdentityCard : reads
CardReader "1" -- "0..*" GuestCard : reads
Reception "1" -- "0..*" GuestCard : collects

@enduml

